#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdio>
using namespace std;

using vi = vector<int>;

void read_int(int& x) {
    scanf("%d", &x);
}

void read_ints(int& a, int& b) {
    scanf("%d %d", &a, &b);
}

void read_ints(int& a, int& b, int& c) {
    scanf("%d %d %d", &a, &b, &c);
}

void read_ints(int& a, int& b, int& c, int& d) {
    scanf("%d %d %d %d", &a, &b, &c, &d);
}

void read_line_int(int& x) {
    scanf("%d\n", &x);
}

void read_line_ints(int& a, int& b) {
    scanf("%d %d\n", &a, &b);
}

void read_line_ints(int& a, int& b, int& c) {
    scanf("%d %d %d\n", &a, &b, &c);
}

void read_line_ints(int& a, int& b, int& c, int& d) {
    scanf("%d %d %d %d\n", &a, &b, &c, &d);
}

void print_int(int x) {
    printf("%d\n", x);
}

void print_int(int a, int b) {
    printf("%d %d\n", a, b);
}

void print_int(int a, int b, int c) {
    printf("%d %d %d\n", a, b, c);
}

void print_int(int a, int b, int c, int d) {
    printf("%d %d %d %d\n", a, b, c, d);
}

void print_int_no_newline(int x) {
    printf("%d", x);
}

void print_int_no_newline(int a, int b) {
    printf("%d %d", a, b);
}

void print_int_no_newline(int a, int b, int c) {
    printf("%d %d %d", a, b, c);
}

void print_int_no_newline(int a, int b, int c, int d) {
    printf("%d %d %d %d", a, b, c, d);
}

void read_vector(vi& v, int n) {
    v.clear();
    for (int i = 0; i < n; ++i) {
        int x;
        read_int(x);
        v.push_back(x);
    }
}

void print_vector(const vi& v) {
    for (size_t i = 0; i < v.size(); ++i) {
        printf("%d%c", v[i], (i == v.size() - 1) ? '\n' : ' ');
    }
}

void compute() {
    int n, t;
    vi nums;
    read_int(n);
    read_vector(nums, n);
    sort(nums.begin(), nums.end());

    int left = 0, right = 0, best = 0;
    read_int(t);

    while (right < n) {
        while (right < n && nums[right] - nums[left] <= t) {
            ++right;
        }
        best = max(best, right - left);
        ++left;
    }

    print_int(best);
}

int main() {
    compute();
    return 0;
}
